import os
import ctypes
import numpy as np
import time

p = 167

# Compute Legendre sequence
QR = set(pow(x, 2, p) for x in range(1, p))
legendre = [0] * p
legendre[0] = 1
for i in range(1, p):
    legendre[i] = 1 if i in QR else -1

# Verify Legendre PAF
leg = np.array(legendre)
paf_check = np.zeros(p)
for k in range(1, p):
    paf_check[k] = sum(leg[i] * leg[(i+k) % p] for i in range(p))
print(f"Legendre PAF at k=1: {int(paf_check[1])}, at k=83: {int(paf_check[83])}")
print(f"All PAFs equal -1: {all(int(paf_check[k]) == -1 for k in range(1, p))}")

c_code = r"""
#include <stdlib.h>
#include <stdio.h>
#include <math.h>
#include <string.h>

/* Goethals-Seidel SA: 4 general (non-symmetric) sequences of length p,
   condition: sum of PAFs at each shift k=1..p-1 equals 0.
   Since PAF(k) = PAF(p-k), we track k=1..m where m=(p-1)/2.
   Defect = 2 * sum_{k=1}^{m} paf_sum[k]^2

   Move: flip a single entry in one sequence.
   Delta PAF for flipping seq[s][j]:
     delta_paf[k] = -2*seq[s][j] * (seq[s][(j+k)%p] + seq[s][(j-k+p)%p])
   for k=1..m. (This accounts for both k and p-k since PAF is symmetric.)

   But wait - we need to be careful. PAF(k) for k=1..p-1.
   PAF(k) = sum_i seq[i]*seq[(i+k)%p]
   PAF(p-k) = sum_i seq[i]*seq[(i+p-k)%p] = sum_i seq[i]*seq[(i-k+p)%p]

   When we flip seq[j], seq[j] -> -seq[j]:
   delta PAF(k) = -2*seq[j]*(seq[(j+k)%p] + seq[(j-k+p)%p])

   But (j+k)%p might equal j (when k=0, excluded) or (j-k+p)%p might equal j (when k=0).
   For k=1..p-1, neither j+k nor j-k equals j mod p. Good.

   However, (j+k)%p might equal (j-k+p)%p when 2k=0 mod p, i.e., k=0 only (p odd). 
   So no overlap. Good.

   For the SYMMETRIC paf_sum stored at indices 1..m:
   paf_sum[k] = PAF(k) + PAF(p-k) summed over all 4 seqs... NO!

   Actually paf_sum[k] just stores the sum of PAF_i(k) for i=1..4.
   Since PAF_i(k) = PAF_i(p-k), paf_sum[k] = paf_sum[p-k].
   Defect = sum_{k=1}^{p-1} paf_sum[k]^2 = 2 * sum_{k=1}^{m} paf_sum[k]^2.

   When we flip seq[s][j]:
   delta_paf_s(k) = -2*old_val * (seq[s][(j+k)%p] + seq[s][(j-k+p)%p])
   This changes paf_sum[k] by the same amount.
   And paf_sum[p-k] changes by the same (they're the same variable).

   New defect contribution from shift k (and p-k):
   2*(paf_sum[k] + delta)^2 instead of 2*paf_sum[k]^2
   Change = 2*(2*paf_sum[k]*delta + delta^2)
*/

int run_gs_sa(int p, int m, int *init_seqs, int *out_seqs, int max_iter, unsigned int seed, 
              double T_start, double T_end) {
    srand(seed);

    int seqs[4][167];
    int paf[4][84]; /* paf[s][k] for k=1..m */
    int paf_sum[84];

    /* Initialize */
    for(int s = 0; s < 4; s++)
        for(int j = 0; j < p; j++)
            seqs[s][j] = init_seqs[s * p + j];

    /* Compute PAFs */
    memset(paf_sum, 0, sizeof(paf_sum));
    for(int s = 0; s < 4; s++) {
        for(int k = 1; k <= m; k++) {
            int sv = 0;
            for(int j = 0; j < p; j++)
                sv += seqs[s][j] * seqs[s][(j + k) % p];
            paf[s][k] = sv;
            paf_sum[k] += sv;
        }
    }

    int current_defect = 0;
    for(int k = 1; k <= m; k++)
        current_defect += 2 * paf_sum[k] * paf_sum[k];

    int best_defect = current_defect;
    for(int s = 0; s < 4; s++)
        for(int j = 0; j < p; j++)
            out_seqs[s * p + j] = seqs[s][j];

    if(best_defect == 0) return 0;

    double T = T_start;
    double alpha = pow(T_end / T_start, 1.0 / max_iter);

    int dp[84];

    for(int iter = 0; iter < max_iter; iter++) {
        T *= alpha;

        int s = rand() % 4;
        int j = rand() % p;
        int old_val = seqs[s][j];

        /* Compute delta for each shift */
        int new_defect = 0;
        for(int k = 1; k <= m; k++) {
            int jk = j + k; if(jk >= p) jk -= p;
            int jmk = j - k; if(jmk < 0) jmk += p;
            dp[k] = -2 * old_val * (seqs[s][jk] + seqs[s][jmk]);
            int ns = paf_sum[k] + dp[k];
            new_defect += 2 * ns * ns;
        }

        int delta = new_defect - current_defect;

        if(delta <= 0 || ((double)rand() / RAND_MAX) < exp(-(double)delta / T)) {
            seqs[s][j] = -old_val;
            current_defect = new_defect;
            for(int k = 1; k <= m; k++) {
                paf[s][k] += dp[k];
                paf_sum[k] += dp[k];
            }

            if(current_defect < best_defect) {
                best_defect = current_defect;
                for(int si = 0; si < 4; si++)
                    for(int ji = 0; ji < p; ji++)
                        out_seqs[si * p + ji] = seqs[si][ji];
                if(best_defect == 0) return 0;
            }
        }
    }
    return best_defect;
}
"""

with open("gs_sa.c", "w") as f:
    f.write(c_code)
os.system("gcc -O3 -shared -fPIC gs_sa.c -o libgssa.so -lm")

lib = ctypes.CDLL("./libgssa.so")
lib.run_gs_sa.restype = ctypes.c_int
lib.run_gs_sa.argtypes = [
