]

# Initialize all 4 sequences as Legendre
init_seqs = np.tile(legendre, 4).astype(np.int32)
init_arr = (ctypes.c_int * (4 * p))(*init_seqs)

best_overall = float('inf')
best_out = None
start = time.time()

for trial in range(100):
    if time.time() - start > 200:
        break

    out_arr = (ctypes.c_int * (4 * p))()
