import os
import ctypes
import numpy as np
import time

p = 167
m = (p - 1) // 2  # 83

# Compute Legendre sequence
QR = set(pow(x, 2, p) for x in range(1, p))
legendre = np.array([1 if (i == 0 or i in QR) else -1 for i in range(p)], dtype=np.int32)

c_code = r"""
