        int s = rand() % 4;
        int j = rand() % p;
        int old_val = seqs[s][j];

        int new_defect = 0;
        for(int k = 1; k <= m; k++) {
            int jk = j + k; if(jk >= p) jk -= p;
            int jmk = j - k; if(jmk < 0) jmk += p;
            dp[k] = -2 * old_val * (seqs[s][jk] + seqs[s][jmk]);
            int ns = paf_sum[k] + dp[k];
            new_defect += 2 * ns * ns;
        }

        int delta = new_defect - current_defect;

        if(delta <= 0 || ((double)rand() / RAND_MAX) < exp(-(double)delta / T)) {
