                paf_sum[k] += dp[k];
            }

            if(current_defect < best_defect) {
                best_defect = current_defect;
                for(int si = 0; si < 4; si++)
                    for(int ji = 0; ji < p; ji++)
                        out_seqs[si * p + ji] = seqs[si][ji];
                if(best_defect == 0) return 0;
            }
        }
    }
    return best_defect;
}
"""

with open("gs_sa2.c", "w") as f:
    f.write(c_code)
os.system("gcc -O3 -shared -fPIC gs_sa2.c -o libgssa2.so -lm")

