    a, b, c, d = best_out[0], best_out[1], best_out[2], best_out[3]

    def make_circulant(first_row):
        n = len(first_row)
        return np.array([np.roll(first_row, i) for i in range(n)])

    A = make_circulant(a)
    B = make_circulant(b)
    C = make_circulant(c)
    D = make_circulant(d)
    R = np.eye(p, dtype=int)[:, ::-1]

    H = np.block([
