# Try multiple sum decompositions
best_overall = None
best_overall_defect = 10**18

for sums in [[25,5,3,3],[21,13,7,3],[23,9,5,3],[23,7,7,3],[19,15,5,3],[25,3,3,3]]:
    if sum(s*s for s in sums) != 4*p:
        continue
    seq_counts = [((p + s) // 2, p - (p + s) // 2) for s in sums]

    for trial in range(3):
        np.random.seed(42 + trial + hash(tuple(sums)) % 1000)
        seqs = []
        for ones, minus_ones in seq_counts:
            s = np.array([1]*ones + [-1]*minus_ones, dtype=np.int8)
            np.random.shuffle(s)
            seqs.append(s)

        pafs = np.array([get_paf_fft(s) for s in seqs])
        total_paf = np.sum(pafs, axis=0)
        defect = int(np.sum(total_paf[1:]**2))
        best_defect = defect
        best_seqs = [s.copy() for s in seqs]

        T = 50.0
        start = time.time()
        while time.time() - start < 8.0:
            for _ in range(200):
                s_idx = np.random.randint(4)
                seq = seqs[s_idx]
                ones_idx = np.where(seq == 1)[0]
                minus_idx = np.where(seq == -1)[0]
                if len(ones_idx) == 0 or len(minus_idx) == 0:
                    continue
                u = ones_idx[np.random.randint(len(ones_idx))]
                v = minus_idx[np.random.randint(len(minus_idx))]
                seq[u], seq[v] = -1, 1
                new_paf = get_paf_fft(seq)
                new_total = total_paf - pafs[s_idx] + new_paf
                new_defect = int(np.sum(new_total[1:]**2))
                delta = new_defect - defect
                if delta < 0 or (T > 0.01 and np.random.random() < np.exp(-delta / max(T, 0.01))):
                    defect = new_defect
                    total_paf = new_total
                    pafs[s_idx] = new_paf
                    if defect < best_defect:
                        best_defect = defect
                        best_seqs = [s.copy() for s in seqs]
                        if defect == 0:
                            break
                else:
                    seq[u], seq[v] = 1, -1
            T *= 0.995
            if defect == 0:
                break

        print(f"sums={sums} trial={trial} best_defect={best_defect}", file=sys.stderr)
        if best_defect < best_overall_defect:
            best_overall_defect = best_defect
            best_overall = [s.copy() for s in best_seqs]
        if best_defect == 0:
            break
    if best_overall_defect == 0:
        break

print(f"Overall best defect: {best_overall_defect}", file=sys.stderr)

a, b, c, d = best_overall

# Build Goethals-Seidel matrix and write to file
# H = [[ A,    B*R,   C*R,   D*R  ],
#      [-B*R,  A,    -D^T*R, C^T*R],
#      [-C*R,  D^T*R, A,    -B^T*R],
#      [-D*R, -C^T*R, B^T*R, A    ]]

def circ(m, i, j):
    return int(m[(j - i) % p])

def circR(m, i, j):
    return int(m[(p - 1 - j - i) % p])

def circTR(m, i, j):
    return int(m[(i - p + 1 + j) % p])

# Write to file
with open('H.csv', 'w') as f:
    for row_idx in range(n):
        block_row = row_idx // p
        i = row_idx % p
        vals = []
        for col_idx in range(n):
            block_col = col_idx // p
            j = col_idx % p

            if block_row == 0:
                if block_col == 0: v = circ(a, i, j)
                elif block_col == 1: v = circR(b, i, j)
                elif block_col == 2: v = circR(c, i, j)
                else: v = circR(d, i, j)
            elif block_row == 1:
                if block_col == 0: v = -circR(b, i, j)
                elif block_col == 1: v = circ(a, i, j)
                elif block_col == 2: v = -circTR(d, i, j)
                else: v = circTR(c, i, j)
            elif block_row == 2:
                if block_col == 0: v = -circR(c, i, j)
                elif block_col == 1: v = circTR(d, i, j)
                elif block_col == 2: v = circ(a, i, j)
                else: v = -circTR(b, i, j)
            else:
                if block_col == 0: v = -circR(d, i, j)
                elif block_col == 1: v = -circTR(c, i, j)
                elif block_col == 2: v = circTR(b, i, j)
                else: v = circ(a, i, j)

            vals.append(str(v))
        f.write(','.join(vals) + '\n')

print(f"Wrote H.csv with {n} rows", file=sys.stderr)

# Verify a few rows
H_check = np.loadtxt('H.csv', delimiter=',', dtype=int)
print(f"H shape: {H_check.shape}", file=sys.stderr)
print(f"All entries +-1: {np.all(np.abs(H_check)==1)}", file=sys.stderr)

# Check HH^T diagonal and a few off-diagonal
diag = np.sum(H_check[0]**2)
print(f"HH^T[0,0] = {diag}", file=sys.stderr)
dot01 = np.dot(H_check[0], H_check[1])
dot02 = np.dot(H_check[0], H_check[2])
print(f"HH^T[0,1] = {dot01}, HH^T[0,2] = {dot02}", file=sys.stderr)

# Now read and print the file
with open('H.csv', 'r') as f:
    content = f.read()
print(content, end='')
